/** A value on a chart's scale and its number as text: the target (8f, "8" → „Ziel 8“) or a grid line (4f, "4"). */
@Immutable
data class SbChartValue(val value: Float, val text: String)

/**
 * How much the screen's text is enlarged: the body size in dp over its size at font scale 1 (Android 14 scales large
 * text non-linearly). The web's rem: a chart measure that the web gives in rem grows by this factor.
 */
@Composable
@ReadOnlyComposable
internal fun sbTextScale(): Float {
    val body = SebaroTheme.typography.body.fontSize
    return with(LocalDensity.current) { body.toDp() / body.value.dp }
}

/**
 * One bar (G1a): [label] under it (two-letter weekdays, spelled-out months, spec/07 §3), [value] its height on the
 * scale, [valueText] its number as text under the label; [current] = the current period (accent bar, title weight).
 */
@Immutable
data class SbBar(val label: String, val value: Float, val valueText: String, val current: Boolean = false)

/**
 * The frame of every chart (spec/02 §3.7, `figure.sb-chart`): [legend] above (G9a), the chart, then [caption] (what,
 * unit, period; „(Beispieldaten)“ on demo data) in caption textMuted, 12 dp apart. TalkBack reads the caption first,
 * as the web names the figure by it, then the chart's own text.
 */
@Composable
fun SbChartFigure(
    caption: String,
    modifier: Modifier = Modifier,
    legend: (@Composable () -> Unit)? = null,
    content: @Composable () -> Unit,
) {
    val t = SebaroTheme.tokens
    Column(
        modifier
            .fillMaxWidth()
            .semantics { isTraversalGroup = true },
        verticalArrangement = Arrangement.spacedBy(t.space.s3),
    ) {
        legend?.invoke()
        content()
        Text(
            caption,
            style = SebaroTheme.typography.caption,
            color = SebaroTheme.colors.textMuted,
            modifier = Modifier.semantics { traversalIndex = -1f },
        )
    }
}

/**
 * Bars, one series (G1a, spec/02 §3.7): grey bars (chartBar), the current period in chartBarCurrent, on a 1 dp base
 * line (chartAxis) in a 128 dp plot under one caption line of head room. [grid] lines are 1 dp chartGrid with their
 * number after the plot; the [target] is 1 dp dashed textMuted over the bars with „Ziel n“ after the plot (both labels
 * hidden from TalkBack: the caption names the target). Under each bar its label (textMuted) over its value (text);
 * TalkBack reads one slot as one node, the current one with the state „aktueller Zeitraum“. [max] = the top of the
 * scale (else the largest of the values, the target and the grid lines); bars start at 0. Every value 0 with nothing
 * above 0 (a week not started) draws the empty chart: the scale runs 0 to 1, no bar has height, the labels and values
 * stand (OR-5; it threw before); a [max] given at 0 or below still throws.
 */
@Composable
fun SbBarChart(
    bars: List<SbBar>,
    caption: String,
    modifier: Modifier = Modifier,
    target: SbChartValue? = null,
    grid: List<SbChartValue> = emptyList(),
    max: Float? = null,
) {
    require(bars.isNotEmpty()) { "SbBarChart: no bars" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val highest = listOfNotNull(bars.maxOf { it.value }, target?.value, grid.maxOfOrNull { it.value }).max()
    val top = max ?: if (highest > 0f) highest else 1f
    require(top > 0f) { "SbBarChart: the top of the scale must be above 0" }
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val plot = t.space.s16 * 2
    val head = with(LocalDensity.current) { ty.caption.lineHeight.toDp() }
    val ends = listOfNotNull(target?.let { it.value to m.chartTarget(it.text) }) + grid.map { it.value to it.text }
    SbChartFigure(caption, modifier) {
        Row(Modifier.fillMaxWidth()) {
            Column(Modifier.weight(1f)) {
                Canvas(
                    Modifier
                        .fillMaxWidth()
                        .padding(top = head)
                        .height(plot),
                ) {
                    val hair = t.borderWidth.hairline.toPx()
                    fun y(v: Float) = size.height * (1f - (v / top).coerceIn(0f, 1f))
                    grid.forEach { g -> drawLine(t.x.chartGrid, Offset(0f, y(g.value)), Offset(size.width, y(g.value)), hair) }
                    val slot = size.width / bars.size
                    val floor = size.height - hair
                    bars.forEachIndexed { i, b ->
                        val at = if (layoutDirection == LayoutDirection.Rtl) bars.size - 1 - i else i
                        val h = floor * (b.value / top).coerceIn(0f, 1f)
                        drawRect(
                            if (b.current) t.x.chartBarCurrent else t.x.chartBar,
                            topLeft = Offset(at * slot + slot * 0.18f, floor - h),
                            size = Size(slot * 0.64f, h),
                        )
                    }
                    drawLine(t.x.chartAxis, Offset(0f, size.height - hair / 2f), Offset(size.width, size.height - hair / 2f), hair)
                    target?.let { g ->
                        val dash = t.space.s1.toPx()
                        drawLine(
                            c.textMuted,
                            Offset(0f, y(g.value)),
                            Offset(size.width, y(g.value)),
                            hair,
                            pathEffect = PathEffect.dashPathEffect(floatArrayOf(dash, dash)),
                        )
                    }
                }
                // D99 (2): a slot whose label or value would touch the next one (two-letter weekdays at a large font
                // scale) is left out, read from the end as the line's axis (§14.22); label and value go together (§14.10:
                // the value row is thinned with the same set) and stay in the slot's TalkBack node. A slot at an edge is
                // moved back inside the chart (room = the row's width), so the last bold label never runs past it
                val measurer = rememberTextMeasurer()
                val bold = text.copy(fontWeight = ty.title.fontWeight)
                val widths = remember(bars, text, measurer) {
                    bars.map {
                        val style = if (it.current) bold else text
                        maxOf(
                            measurer.measure(it.label, style, softWrap = false, maxLines = 1).size.width,
                            measurer.measure(it.valueText, style, softWrap = false, maxLines = 1).size.width,
                        )
                    }
                }
                BoxWithConstraints(
                    Modifier
                        .fillMaxWidth()
                        .padding(top = t.space.s1),
                ) {
                    val room = constraints.maxWidth.toFloat()
                    val slot = room / bars.size
                    val gapPx = with(LocalDensity.current) { t.space.s1.toPx() }
                    val shown = sbShownLabels(List(bars.size) { slot * (it + 0.5f) }, widths, gapPx, room)
                    Row(Modifier.fillMaxWidth()) {
                        bars.forEachIndexed { i, b ->
                            val style = if (b.current) bold else text
                            // the slot's text is centred on its bar; at an edge it is moved back inside the row (the
                            // offset follows the layout direction, so a mirrored row moves it the same way). The place is
                            // sbLabelFrom, the one sbShownLabels checks (§50: the check left out the clamp at 0, so the
                            // first date label stood further in than checked and touched the next). A text wider than its
                            // slot is measured unbounded and centred on it (it was clamped to the slot and ran on to the
                            // right from the slot's left edge, so it was not centred where it was checked)
                            val centre = slot * (i + 0.5f)
                            val shift = (sbLabelFrom(centre, widths[i].toFloat(), room) - (centre - widths[i] / 2f)).roundToInt()
                            val place = Modifier
                                .wrapContentWidth(unbounded = true)
                                .offset { IntOffset(shift, 0) }
                                .then(if (shown[i]) Modifier else Modifier.alpha(0f))
                            Column(
                                Modifier
                                    .weight(1f)
                                    .semantics(mergeDescendants = true) { if (b.current) stateDescription = m.chartCurrent },
                                horizontalAlignment = Alignment.CenterHorizontally,
                            ) {
                                Text(
                                    b.label,
                                    style = style,
                                    color = if (b.current) c.text else c.textMuted,
                                    softWrap = false,
                                    overflow = TextOverflow.Visible,
                                    modifier = place,
                                )
                                Text(b.valueText, style = style, color = c.text, softWrap = false, overflow = TextOverflow.Visible, modifier = place)
                            }
                        }
                    }
                }
            }
            if (ends.isNotEmpty()) SbChartEnds(ends, top, head, plot)
        }
    }
}

/**
 * Where a label [width] px wide, centred on [centre], starts in a row [room] px wide (left to right): moved back to end
 * at [room] when it would run past it, and never before 0. The one place both drawing and [sbShownLabels] use.
 */
internal fun sbLabelFrom(centre: Float, width: Float, room: Float): Float =
    minOf(centre - width / 2f, room - width).coerceAtLeast(0f)

/**
 * Which labels of a row may be drawn (D99 (2)): each label [widths] px wide starts where [sbLabelFrom] puts it on its
 * place in [centres] (the caller draws it there); read from the end, a label stays
 * when it ends at least [gap] px before the next label shown, so the latest labels stay and none is left out for a
 * label that is left out itself (as the line's axis, §14.22). Left out means not drawn; the caller keeps its word for
 * TalkBack. Left to right positions; mirrored rows give the same set.
 */
internal fun sbShownLabels(centres: List<Float>, widths: List<Int>, gap: Float, room: Float = Float.MAX_VALUE): List<Boolean> {
    val shown = MutableList(widths.size) { false }
    var limit = Float.MAX_VALUE
    for (i in widths.indices.reversed()) {
        val from = sbLabelFrom(centres[i], widths[i].toFloat(), room)
        if (from + widths[i] <= limit) {
            shown[i] = true
            limit = from - gap
        }
    }
    return shown
}

/** Labels after the plot (`sb-chart__ends`): each centred on its value, caption textMuted, hidden from TalkBack. */
@Composable
private fun SbChartEnds(ends: List<Pair<Float, String>>, top: Float, head: Dp, plot: Dp) {
    val ty = SebaroTheme.typography
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    Layout(
        content = {
            ends.forEach { (_, label) -> Text(label, style = text, color = SebaroTheme.colors.textMuted, softWrap = false) }
        },
        modifier = Modifier
            .padding(start = SebaroTheme.tokens.space.s2)
            .clearAndSetSemantics { },
    ) { measurables, _ ->
        val placeables = measurables.map { it.measure(Constraints()) }
        val headPx = head.roundToPx()
        val plotPx = plot.roundToPx()
        layout(placeables.maxOf { it.width }, headPx + plotPx) {
            placeables.forEachIndexed { i, p ->
                val y = headPx + plotPx * (1f - (ends[i].first / top).coerceIn(0f, 1f))
                p.placeRelative(0, (y - p.height / 2f).roundToInt())
            }
        }
    }
}
